pair D, P, R, V;

D = (3,1);
V = (1.5,2);
R = reflect((0,0),D)*(V);
P = (V + R)/2;

draw((-1,0)--(4,0));
draw((0,-1)--(0,3));
draw((0,0)--D,Arrow(6));
draw((0,0)--V,red,Arrow(6));
draw((0,0)--R,blue,Arrow(6));
draw(V--R,dashed);

label("$\mathbf{v}$", V, NE);
label("$\mathbf{r}$", R, SE);
