draw((1,0)--(1,-2));
draw((1.76,0)--(1.76,-2));

draw((1,-2)..(1.38,-2.114)..(1.76,-2));
path p =(1.38,-2.114)..(1.74,-1.5)..(1,-0.5)..(1.38,-.114);
pair a=(1.38,-2.114), b=(1.76,-1.5);
path q =subpath(p, 1, 2);
path r=subpath(p,0,1);
path s=subpath(p,2,3);
