\end{align*}
So it suffices that to show
\begin{align*}
\sum_{n=0}^{\infty}\frac{n}{n^2-n+1}+\sum_{n=2}^{\infty}\frac{n-1}{n^2+n+1}=\frac{1}{2}.
\end{align*}
Indeed,
\begin{align*}
\sum_{n=0}^{\infty}\frac{n}{n^2+n+1}+\sum_{n=2}^{\infty}\frac{n-1}{n^2+n+1}&=1\\
\sum_{n=0}^{\infty}\frac{n}{n^2+n+1}+\sum_{n=2}^{\infty}\frac{n-1}{n^2+n+1}&=\sum_{n=2}^{\infty}\frac{n}{n^2+n+1}\\
